 schemes jsonb := '{"p2e-q3::a":[{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Plot and label point A accurately","check":{"type":"manual-verification","evidence":"Inspect plot location (-4, -1) on original coordinate axes and label A"},"code":"B1"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Plot and label point B accurately","check":{"type":"manual-verification","evidence":"Inspect plot location (2, 8) on original coordinate axes and label B"},"code":"B2"}],"p2e-q4::a1":[{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Source-accurate first compass arc","check":{"type":"manual-verification","evidence":"Arc from A at radius 7 cm above given AB=9 cm"},"code":"B1"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Source-accurate intersecting second arc","check":{"type":"manual-verification","evidence":"Arc from B at radius 6 cm intersects first at C"},"code":"B2"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Completed triangle with visible construction evidence","check":{"type":"manual-verification","evidence":"Join AC and BC, show both arcs, lengths AC=7 cm, BC=6 cm, AB=9 cm"},"code":"B3"}],"p2e-q5::a":[{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"First two correctly positioned class midpoints","check":{"type":"manual-verification","evidence":"Inspect exact table cells for midpoints 25.5, 35.5"},"code":"B1"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Third class midpoint and first f×x product","check":{"type":"manual-verification","evidence":"Inspect labelled cells midpoint 45.5 and first product 357"},"code":"B2"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Remaining f×x products","check":{"type":"manual-verification