ks":1,"field":"all","depends":[],"profile":"visual-source","description":"Accurately plotted first section of quadratic","check":{"type":"manual-verification","evidence":"Verify plotted coordinate artifacts against source quadratic: Plot the seven points from the table and join them with a single smooth curve. Do not join them with straight lines.; check at least the first three source table points"},"code":"B1"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Accurately plotted remaining quadratic points","check":{"type":"manual-verification","evidence":"Verify all remaining source table points and positional alignment to original x/y axis scales: Plot the seven points from the table and join them with a single smooth curve. Do not join them with straight lines."},"code":"B2"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Correct axes and curve placement","check":{"type":"manual-verification","evidence":"Inspect positive/negative orientation, scale and labelled quadratic graph corresponding to the points (-2, 5) to (4, 5) joined by a smooth curve"},"code":"B3"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Single smooth quadratic curve","check":{"type":"manual-verification","evidence":"Inspect plotted curve passing through source points; straight-line segmented joins do not earn this mark"},"code":"B4"}],"p2g-q3::a":[{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Plot and label point A accurately","check":{"type":"manual-verification","evidence":"Inspect plot location (-5, 6) on original coordinate axes and label A"},"code":"B1"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Plot and label point B accurately","check":{"type":"manual-verification","evidence":"Inspect plot location (3, 2) on original coordinate axes and label B"},"code":"B2"}],"p2g-q4::a