:1,"field":"all","depends":[],"profile":"visual-source","description":"Correct Figure 5 dot-count cell","check":{"type":"manual-verification","evidence":"Inspect correct labelled response location for 30; verify algebraic equivalence only in the final expression"},"code":"B2"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Correct Figure 10 dot-count cell","check":{"type":"manual-verification","evidence":"Inspect correct labelled response location for 110; verify algebraic equivalence only in the final expression"},"code":"B3"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Correct general nth-term pattern expression","check":{"type":"manual-verification","evidence":"Inspect correct labelled response location for n(n + 1); verify algebraic equivalence only in the final expression"},"code":"B4"}],"p2g-q8::a":[{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Correct quadratic table value 1","check":{"type":"manual-verification","evidence":"Inspect numeric value -5 in its designated table cell; do not infer table position from unordered text"},"code":"B1"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Correct quadratic table value 2","check":{"type":"manual-verification","evidence":"Inspect numeric value -5 in its designated table cell; do not infer table position from unordered text"},"code":"B2"}],"p2g-q8::b":[{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Accurately plotted first section of quadratic","check":{"type":"manual-verification","evidence":"Verify plotted coordinate artifacts against source quadratic: Plot the seven points from the table and join them with a single smooth curve. Do not join them with straight lines.; check at least the first three source table points"},"code":"B1"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Accurately plotted remaining quadratic points","check":{"type":"manual-verification","evidence":"Verify all remaining source table points and positional alignment to original x/y axis scales: Plot the seven points from the table and join them with a single smooth curve. Do not join them with straight lines."},"code":"B2"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Correct axes and curve placement","check":{"type":"manual-verification","evidence":"Inspect positive/negative orientation, scale and labelled quadratic graph corresponding to the points (-5, 7) to (3, 7) joined by a smooth curve"},"code":"B3"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Single smooth quadratic curve","check":{"type":"manual-verification","evidence":"Inspect plotted curve passing through source points; straight-line segmented joins do not earn this mark"},"code":"B4"}],"p2i-q3::a":[{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Plot and label point A accurately","check":{"type":"manual-verification","evidence":"Inspect plot location (-2, -3) on original coordinate axes and label A"},"code":"B1"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Plot and label point B accurately","check":{"type":"manual-verification","evidence":"Inspect plot location (3, 7) on original coordinate axes and label B"},"code":"B2"}],"p2i-q4::a1":[{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Source-accurate first compass arc","check":{"type":"manual-verification","evidence":"Arc from A at radius 6 cm above given AB=6 cm"},"code":"B1"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Source-accurate intersecting second arc","check":{"type":"manual-verification","evidence":"Arc from B at same radius 6 cm intersects first at C"},"code":"B2"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Completed triangle with visible construction evidence","check":{"type":"manual-verification","evidence":"Join AC and BC, retain both arcs, three sides 6 cm and angle CAB=60 degrees"},"code":"B3"}],"p2i-q5::a":[{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"First two correctly positioned class midpoints","check":{"type":"manual-verification","evidence":"Inspect exact table cells for midpoints 35.5, 45.5"},"code":"B1"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Third class midpoint and first f×x product","check":{"type":"manual-verification","evidence":"Inspect labelled cells midpoint 55.5 and first product 710"},"code":"B2"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Remaining f×x products","check":{"type":"manual-verification","evidence":"Inspect labelled cells for 500.5 and 333; accept independently correct entries despite earlier mistakes where justified"},"code":"B3"}],"p2i-q7::a":[{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Correct Figure 4 dot-count cell","check":{"type":"manual-verification","evidence":"Inspect correct labelled response location for 36; verify algebraic equivalence only in the final expression"},"code":"B1"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Correct Figure 5 dot-count cell","check":{"type":"manual-verification","evidence":"Inspect correct labelled response location for 55; verify algebraic equivalence only in the final expression"},"code":"B2"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Correct Figure 10 dot-count cell","check":{"type":"manual-verification","evidence":"Inspect correct labelled response location for 210; verify algebraic equivalence only in the final expression"},"code":"B3"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Correct general nth-term pattern expression","check":{"type":"manual-verification","evidence":"Inspect correct labelled response location for 2n^2 + n; verify algebraic equivalence only in the final expression"},"code":"B4"}],"p2i-q8::a":[{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Correct quadratic table value 1","check":{"type":"manual-verification","evidence":"Inspect numeric value -3 in its designated table cell; do not infer table position from unordered text"},"code":"B1"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Correct quadratic table value 2","check":{"type":"manual-verification","evidence":"Inspect numeric value -3 in its designated table cell; do not infer table position from unordered text"},"code":"B2"}],"p2i-q8::b":[{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Accurately plotted first section of quadratic","check":{"type":"manual-verification","evidence":"Verify plotted coordinate artifacts against source quadratic: Plot the seven points from the table and join them with a single smooth curve. Do not join them with straight lines.; check at least the first three source table points"},"code":"B1"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Accurately plotted remaining quadratic points","check":{"type":"manual-verification","evidence":"Verify all remaining source table points and positional alignment to original x/y axis scales: Plot the seven points from the table and join them with a single smooth curve. Do not join them with straight lines."},"code":"B2"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Correct axes and curve placement","check":{"type":"manual-verification","evidence":"Inspect positive/negative orientation, scale and labelled quadratic graph corresponding to the points (0, 5) to (6, 5) joined by a smooth curve"},"code":"B3"},{"kind":"B","marks":1,"field":"all","depends":[],"profile":"visual-source","description":"Single smooth quadratic curve","check":{"type":"manual-verification","evidence":"Inspect plotted curve passing through source points; straight-line segmented joins do not earn this mark"},"code":"B4"}]}'::jsonb;
 answers jsonb := '{"p2e-q3::a":"A(-4, -1) and B(2, 8) correctly plotted","p2e-q4::a1":"triangle ABC with AB = 9 cm, BC = 6 cm and AC = 7 cm, with the arcs that locate C clearly shown","p2e-q5::a":"25.5, 35.5, 45.5; 357, 248.5, 136.5","p2e-q7::a":"10, 15, 55, n(n + 1)/2","p2e-q8::a":"-3, -3","p2e-q8::b":"the points (-2, 5) to (4, 5) joined by a smooth curve","p2g-q3::a":"A(-5, 6) and B(3, 2) correctly plotted","p2g-q4::a1":"the perpendicular bisector of AB, with the construction arcs shown","p2g-q5::a":"25.5, 35.5, 45.5; 459, 461.5, 273","p2g-q7::a":"20, 30, 110, n(n + 1)","p2g-q8::a":"-5, -5","p2g-q8::b":"the points (-5, 7) to (3, 7) joined by a smooth curve","p2i-q3::a":"A(-2, -3) and B(3, 7) correctly plotted","p2i-q4::a1":"the equilateral triangle ABC of side 6 cm standing on AB, giving angle CAB = 60°, with the two arcs shown","p2i-q5::a":"35.5, 45.5, 55.5; 710, 500.5, 333","p2i-q7::a":"36, 55, 210, 2n^2 + n","p2i-q8::a":"-3, -3","p2i-q8::b":"the points (0, 5) to (6, 5) joined by a smooth curve"}'::jsonb;
 paper text; rub spark_grading_private.rubrics_v2%rowtype;
 revised jsonb; found_parts integer; invalid_parts integer; desired integer;
BEGIN
 FOREACH paper IN ARRAY ARRAY['p2e','p2g','p2i'] LOOP
  desired := CASE WHEN paper='p2i' THEN 40 ELSE 42 END;
  SELECT * INTO rub FROM spark_grading_private.rubrics_v2
   WHERE subject_id='mathematics' AND paper_id=paper
     AND rubric_version='source-scheme-draft-v2' FOR UPDATE;
  IF NOT FOUND OR rub.active OR rub.verification_status <> 'draft'
    OR rub.verified_by IS NOT NULL OR rub.verified_at IS NOT NULL
    OR rub.source_sha256 IS DISTINCT FROM encode(sha256(convert_to(rub.criteria::text,'UTF8')),'hex')
  THEN RAISE EXCEPTION 'Practice source hash/status changed: %',paper; END IF;
  IF jsonb_array_length(rub.criteria) <> desired
  THEN RAISE EXCEPTION 'Unexpected Practice paper part count: %',paper; END IF;
  SELECT count(*), count(*) FILTER(WHERE
    c->>'id' IS DISTINCT FROM c->>'sourcePartId'
    OR c->'sourceMarking'->>'answer' IS DISTINCT FROM answers->>(c->>'id')
    OR jsonb_typeof(c->'sourceMarking'->'criteria') IS DISTINCT FROM 'null'
    OR (c->>'maxMarks')::integer IS DISTINCT FROM
       (SELECT sum((m->>'marks')::integer)
          FROM jsonb_array_elements(schemes->(c->>'id')) m)
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(schemes->(c->>'id')) m
      WHERE m->'check'->>'type' <> 'manual-verification')
  ) INTO found_parts,invalid_parts
  FROM jsonb_array_elements(rub.criteria)c
  WHERE schemes ? (c->>'id') AND c->>'id' LIKE paper||'-%';
  IF found_parts <> 6 OR invalid_parts <> 0 THEN
    RAISE EXCEPTION 'Practice E/G/I six source parts mismatch for %: found %, invalid %',
      paper, found_parts, invalid_parts; END IF;
  SELECT jsonb_agg(
    CASE WHEN schemes ? (c.value->>'id')
      THEN jsonb_set(c.value,'{sourceMarking,criteria}',schemes->(c.value->>'id'))
      ELSE c.value END ORDER BY c.ordinal)
    INTO revised FROM jsonb_array_elements(rub.criteria) WITH ORDINALITY c(value,ordinal);
  IF jsonb_array_length(revised)<>desired
    OR (SELECT count(*) FROM jsonb_array_elements(revised)c
         WHERE jsonb_typeof(c->'sourceMarking'->'criteria')='array'
           AND jsonb_array_length(c->'sourceMarking'->'criteria')>0)<>desired
    OR (SELECT sum((c->>'maxMarks')::integer) FROM jsonb_array_elements(revised)c)<>100
  THEN RAISE EXCEPTION 'Incomplete source-calibrated Practice paper %',paper; END IF;
  UPDATE spark_grading_private.rubrics_v2
    SET criteria=revised,
        source_sha256=encode(sha256(convert_to(revised::text,'UTF8')),'hex')
   WHERE subject_id='mathematics' AND paper_id=paper
     AND rubric_version='source-scheme-draft-v2'
     AND active=false AND verification_status='draft';
  IF NOT FOUND THEN RAISE EXCEPTION 'Failed guarded update: %',paper; END IF;
 END LOOP;
END $calibrate$;
COMMIT;
